<script setup lang="ts">import {computed} from 'vue';import type {ComparisonResult} from '../types/domain';import {num} from '../utils/format';const props=defineProps<{diff:ComparisonResult['diff']}>();
const bounds=computed(()=>{const lo=Math.min(props.diff.histogram[0].left,0),hi=Math.max(props.diff.histogram.at(-1)!.right,0);return {lo,hi:hi===lo?hi+1:hi,max:Math.max(...props.diff.histogram.map(b=>b.count))}});
const x=(v:number)=>56+(v-bounds.value.lo)/(bounds.value.hi-bounds.value.lo)*790;const y=(v:number)=>290-v/bounds.value.max*240;
const fill=(left:number,right:number)=>right<=0?'#ac6c47':left>=0?'#8f9077':(left+right)/2<0?'#b98a68':'#a8a58c';</script><template><div class="histogram"><div class="plot-title"><strong>工期差样本分布（对比 − 基准）</strong><span>小时 / {{diff.denominator}}次配对抽样 · 负值为提前</span></div><svg viewBox="0 0 900 345" role="img" aria-label="配对比较工期差分布"><g v-for="f in [0,.25,.5,.75,1]" :key="f"><line x1="56" x2="846" :y1="y(f*bounds.max)" :y2="y(f*bounds.max)" stroke="#d7d1c3"/><text x="44" :y="y(f*bounds.max)+4" text-anchor="end">{{Math.round(f*bounds.max)}}</text></g><rect v-for="(bin,i) in diff.histogram" :key="i" :x="x(bin.left)" :y="y(bin.count)" :width="Math.max(5,x(bin.right)-x(bin.left)-2)" :height="290-y(bin.count)" :fill="fill(bin.left,bin.right)"><title>{{num(bin.left)}}—{{num(bin.right)}}小时：{{bin.count}}样本</title></rect><line :x1="x(0)" :x2="x(0)" y1="22" y2="295" stroke="#5c5546" stroke-dasharray="5 3" stroke-width="2"/><text :x="Math.min(780,x(0)+7)" y="18">持平线 0h</text><text v-for="f in [0,.25,.5,.75,1]" :key="f" :x="x(bounds.lo+f*(bounds.hi-bounds.lo))" y="319" text-anchor="middle">{{num(bounds.lo+f*(bounds.hi-bounds.lo),1)}}</text></svg></div></template>
